import {TODAY, purchaseError, claimWindow, reminderDecision, walletView} from './order-model.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'₹'+Number(n).toLocaleString('en-IN',{maximumFractionDigits:2});
const date=d=>new Date(d+'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Kolkata'});
const merchants={flipkart:{name:'Flipkart',benefit:'cash cashback',unit:'Cashback',source:'https://cashkaro.com/stores/flipkart',timing:'Tracking guidance differs across the public page. Check the current store terms; this example does not promise an exact tracking time.',confirm:'The store describes confirmation after the return/exchange period and retailer reporting, which can take up to 35 days.'},amazon:{name:'Amazon',benefit:'gift-card Rewards',unit:'Rewards',source:'https://cashkaro.com/stores/amazon',timing:'The store describes tracking within 48 hours after shipment. A click-out cannot tell us when an order shipped.',confirm:'Confirmation follows the return/exchange period and retailer reporting. The store describes up to 30 days, with some categories taking up to 80.'}};
let s, toastTimer;
function reset(scenario='fresh') {
 const older=['missing','tracked','confirmed','cancelled'].includes(scenario), late=['reminder','expired'].includes(scenario);
 const start=late?(scenario==='expired'?'2026-08-01':'2026-08-14'):older?'2026-09-04':TODAY;
 s={merchant:$('#merchant').value,scenario,visitDate:start,bought:older||late,purchaseDate:older||late?start:'',state:['tracked','confirmed','cancelled'].includes(scenario)?scenario:'visit',form:false,optedIn:false,alreadyNotified:false,draft:false,policy:$('#policy-mode').value};
 render();
}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function focusStatus(){const h=$('#status-content h3');h?.setAttribute('tabindex','-1');h?.focus({preventScroll:true});}
function terms(){const m=merchants[s.merchant];$('#merchant-terms').innerHTML=`<p class="benefit-type">${m.benefit==='cash cashback'?'Eligible cashback can become bank-withdrawable.':'Rewards are for gift-card redemption, not bank cash.'}</p><div class="rule-focus"><h3>Add items to the retailer cart only after going through CashKaro.</h3><p>One important rule, not the full eligibility check. Rates, exclusions and other conditions depend on the category and offer.</p><a href="${m.source}" target="_blank" rel="noopener noreferrer">Read ${m.name} rates & full terms ↗</a></div>`;$('#start-visit').textContent=`Continue to ${m.name} · demo ↗`;$('#start-visit').disabled=s.scenario==='unavailable';}
function wallet(){const observed=s.state==='confirmed',v=walletView(180+(observed&&s.merchant==='flipkart'?90:0),80+(observed&&s.merchant==='amazon'?90:0),s.state==='tracked'?90:0);$('#wallet').innerHTML=`<div class="balance-row"><strong>${money(v.cash)}</strong><span>Confirmed cash cashback</span></div><div class="balance-row"><strong>${money(v.rewards)}</strong><span>Confirmed gift-card Rewards</span></div>${v.pending?`<p class="note">${money(v.pending)} pending · excluded below</p>`:''}<hr class="wallet-divider"><div class="wallet-progress"><strong>Bank transfer ${v.bankAvailable?'available':`· ${money(v.bankGap)} to the minimum`}</strong><progress value="${Math.min(v.cash,250)}" max="250" aria-label="Confirmed cash towards the 250 rupee bank transfer minimum"></progress><span>${money(v.cash)} confirmed cash / ₹250 minimum</span></div><div class="wallet-progress"><strong>Gift-card redemption ${v.giftAvailable?'available':`· ${money(v.giftGap)} to the minimum`}</strong><span>${money(v.cash+v.rewards)} confirmed cash + Rewards / ₹250 minimum</span></div>`;}
function card(label,title,body,actions='',tone=''){return `<div class="status-card ${tone}"><span class="status-label">${label}</span><h3>${title}</h3>${body}${actions?`<div class="status-actions">${actions}</div>`:''}</div>`;}
const button=(action,text,primary=false)=>`<button type="button" data-action="${action}" class="button ${primary?'primary':''}">${text}</button>`;
function render(){const m=merchants[s.merchant],w=claimWindow(s);terms();wallet();$('#receipt-title').textContent=m.name;$('#receipt-id').textContent=s.scenario==='unavailable'?'NO NEW RECEIPT':'DEMO / VISIT 001';$('#receipt-context').innerHTML=s.scenario==='unavailable'?'<p class="notice">The example policy service is unavailable.</p>':`<div class="receipt-context"><span>Visited ${date(s.visitDate)}</span><span>${m.benefit}</span><span>Reference policy · 11 Sep 2026</span></div>`;
 let html='';
 if(s.scenario==='unavailable') html=card('Information unavailable','We can’t save reliable guidance right now.','<p>Try again when the policy service recovers, or read the retailer’s current CashKaro terms. This example has not created a new visit or activated cashback.</p>',button('restore','Restore service · demo',true),'amber');
 else if(s.state==='no-order') html=card('Visit closed','No order. Nothing to chase.','<p>This visit remains separate from your orders. No missing-order reminder will be generated for it.</p>',button('undo-no-order','I did place an order'));
 else if(['tracked','confirmed','cancelled'].includes(s.state)){
  const pending=s.state==='tracked',confirmed=s.state==='confirmed';
  html=card(pending?'Retailer acknowledgement · simulated':confirmed?'Retailer confirmation · simulated':'Retailer decision · simulated',pending?`${m.unit} tracked. Still pending.`:confirmed?`${m.unit} confirmed.`:`This order’s ${m.unit.toLowerCase()} was declined.`,`${s.state!=='cancelled'?'<p class="status-money">₹90</p>':''}<p>${pending?`The retailer has acknowledged this example order. ${m.confirm} It is not available to redeem yet.`:confirmed?`${s.merchant==='amazon'?'₹90 has been added to gift-card Rewards. It cannot be withdrawn to a bank.':'₹90 has been added to confirmed cash cashback.'} See the updated example wallet.`:'Example reason: the order was returned. If that is incorrect, ask support to review the decision with the order details.'}</p><p class="evidence-badge">Example merchant event and amount. No live order feed is connected. A pending amount may be adjusted or reversed.</p>`,s.state==='cancelled'?button('support','Prepare a status enquiry',true):'',s.state==='cancelled'?'amber':'green');
 }else if(s.form){html=card('Tell us what happened','When did you place the order?',`<p>Use the purchase date from your order confirmation. The visit date stays attached separately.</p><form id="purchase-form" class="purchase-form"><label for="purchase-date">Purchase date<input id="purchase-date" type="date" min="${s.visitDate}" max="${TODAY}" value="${s.purchaseDate||s.visitDate}" required></label><p id="purchase-error" class="field-error" role="alert"></p><button type="submit" class="button primary">Save purchase date</button><button type="button" data-action="cancel-date" class="text-button">Cancel</button></form>`);
 }else if(!s.bought){html=card('Visit saved · purchase unknown','Did you place an order?',`<p>We recorded your visit to ${m.name}. A visit alone doesn’t tell us whether you bought anything.</p><p>${m.timing}</p>`,button('bought','Yes, I ordered',true)+button('no-order','No order')+button('later','I’ll check later'));
 }else{let heading,body,actions='';
  if(w.kind==='conflict'){heading='Your order is reported. The next step needs a check.';body='<p>There is no tracking update in this example. That does not establish why, or whether the order qualifies.</p><p>The store terms say 30 days to report a missing order; general help says 10. We can’t give you a reliable deadline from conflicting guidance. Contact support promptly to confirm your window.</p>';actions=button('support','Prepare details for support',true);}
  else if(w.kind==='early'){heading='Your order is reported. Give tracking time.';body=`<p>The illustrative policy opens missing-order enquiries on ${date(w.opens)}. Tracking may arrive before then.</p><p>${m.timing}</p>`;}
  else if(w.kind==='expired'){heading='The example reporting window has passed.';body=`<p>The illustrative policy closed on ${date(w.closes)}. A late claim is not promised. Ask support whether any review is available for your circumstances.</p>`;actions=button('support','Prepare a support enquiry',true);}
  else {heading='No tracking update yet. You can ask for a check.';body=`<p>You reported a purchase on ${date(s.purchaseDate)}. Under the illustrative reviewed policy, report it by <strong>${date(w.closes)}</strong>.</p><p>A missing update is not a payout decision. Keep your order reference ready for support.</p>`;actions=button('support','Prepare missing-order details',true);}
  html=card(w.kind==='conflict'?'Guidance conflict':w.kind==='early'?'Waiting for an update':'Purchase reported · no retailer update',heading,body+`<p class="evidence-badge">Purchase date supplied by you · ${date(s.purchaseDate)}. ${s.policy==='approved'?'Dates use a simulated reviewed policy, not approved CashKaro terms.':'No automated deadline or reminder is enabled.'}</p>`,actions,'amber');
  if(s.draft)html+='<p class="notice">Support draft prepared in this demo. Nothing has been submitted. Keep the details and follow the official support instructions.</p>';
  html+=`<div class="status-actions auxiliary">${button('edit-date','Correct purchase date')}${button('no-order','Actually, no order')}</div>`;
 }
 if(s.scenario!=='unavailable'&&!s.form&&s.state!=='no-order') html+=`<div class="reminder-box"><label><input id="reminder-optin" type="checkbox" ${s.optedIn?'checked':''}>Remind me if this reported order needs action</label><p>Optional. One service reminder per visit, at most one per account per day in the proposed service. No shopping promotions. Turn it off here.</p><p id="reminder-reason"></p><button type="button" data-action="preview-reminder" class="button small" id="preview-reminder">Preview an eligible reminder</button><div id="message-preview"></div></div>`;
 $('#status-content').innerHTML=html;
 $('#history').innerHTML=s.scenario==='unavailable'?'':`<h3 class="timeline-title">What this receipt knows</h3><ol class="event-list"><li><strong>Retailer visit saved</strong><small>${date(s.visitDate)} · CashKaro click-out record, simulated</small></li>${s.bought?`<li><strong>Purchase reported</strong><small>${date(s.purchaseDate)} · supplied by you, not verified by the retailer</small></li>`:''}${['tracked','confirmed','cancelled'].includes(s.state)?`<li><strong>${s.state==='tracked'?'Pending acknowledgement':s.state==='confirmed'?'Confirmed benefit':'Declined benefit'}</strong><small>Simulated retailer event · ₹90 example benefit</small></li>`:s.state==='no-order'?'<li><strong>You said no order</strong><small>Recovery messages suppressed</small></li>':'<li><strong>No retailer event in this example</strong><small>Purchase and attribution cannot be inferred from silence</small></li>'}${s.draft?'<li><strong>Support draft prepared</strong><small>Not submitted · no claim status inferred</small></li>':''}</ol>`;
 $('#saved-policy').innerHTML=`<p><strong>Key rule:</strong> add items to the retailer’s cart only after visiting through CashKaro. Full rates and exclusions still apply.</p><p>${m.timing}</p><p>${s.policy==='approved'?'Illustrative policy DEMO-30-v1: enquiries from purchase day +3 through day +30, using a fixed demo date and India calendar dates. This is a scenario input, not partner approval.':'Public source snapshot: merchant-specific 30-day claim guidance conflicts with generic 10-day help. A responsible operations owner must resolve the applicable rule.'}</p><a href="${m.source}" target="_blank" rel="noopener noreferrer">${m.name} source terms ↗</a> · <a href="https://cashkaro.com/how-it-works" target="_blank" rel="noopener noreferrer">General help ↗</a>`;
 reminder();
 $('#purchase-form')?.addEventListener('submit',e=>{e.preventDefault();const d=$('#purchase-date').value,error=purchaseError(d,s.visitDate);if(error){$('#purchase-error').textContent=error;return;}s.purchaseDate=d;s.bought=true;s.form=false;s.draft=false;render();focusStatus();});
 $('#reminder-optin')?.addEventListener('change',e=>{s.optedIn=e.target.checked;reminder();});
}
function reminder(){if(!$('#reminder-reason'))return;const r=reminderDecision(s);$('#reminder-reason').textContent=r.eligible?'Eligible in this scenario: the verified example window closes within three days.':r.reason;$('#preview-reminder').disabled=!r.eligible;$('#message-preview').innerHTML='';}
function support(){const m=merchants[s.merchant];$('#support-summary').innerHTML=`<strong>${m.name}</strong><br>Visit: ${date(s.visitDate)}<br>Purchase reported: ${date(s.purchaseDate)}<br>Benefit: ${m.benefit}<br>Policy: ${s.policy==='approved'?'Illustrative DEMO-30-v1':'Public-source conflict; confirm with support'}<br>Visit reference: DEMO-VISIT-001`;$('#support-form').reset();$('#support-result').replaceChildren();$('#support-dialog').showModal();}
$('#status-content').addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;
 if(action==='bought'||action==='edit-date'||action==='undo-no-order'){s.state='visit';s.form=true;render();$('#purchase-date')?.focus();}
 else if(action==='no-order'){s.state='no-order';s.bought=false;s.purchaseDate='';s.optedIn=false;s.draft=false;render();focusStatus();}
 else if(action==='cancel-date'){s.form=false;render();focusStatus();}
 else if(action==='later'){toast('Visit kept. No missing-order reminder is scheduled.');}
 else if(action==='restore'){ $('#demo-scenario').value='fresh';reset();toast('Example service restored. You can start a visit.');}
 else if(action==='support'){support();}
 else if(action==='preview-reminder'){const r=reminderDecision(s);if(!r.eligible)return;s.alreadyNotified=true;$('#message-preview').innerHTML=`<div class="message-preview"><strong>Your ${merchants[s.merchant].name} order needs a check.</strong><p>You reported a purchase on ${date(s.purchaseDate)}. There is no tracking update yet. The example claim window closes ${date(r.date)}. Open the receipt to review your next step.</p><p class="note">In-page preview only. No push permission requested or message sent.</p></div>`;$('#preview-reminder').disabled=true;$('#reminder-reason').textContent='Reminder previewed once. Duplicate preview suppressed for this visit.';}
});
$('#support-form').addEventListener('submit',e=>{e.preventDefault();const ref=$('#order-id').value.trim(),amount=Number($('#order-amount').value);if(!ref||!Number.isFinite(amount)||amount<=0||amount>1000000)return;s.draft=true;const text=`DEMO SUPPORT DRAFT — NOT SUBMITTED
Retailer: ${merchants[s.merchant].name}
Saved visit: ${s.visitDate} / DEMO-VISIT-001
User-reported purchase: ${s.purchaseDate}
Example order reference: ${ref}
Example amount paid: ${money(amount)}
Current state: ${s.state==='cancelled'?'Declined benefit; review requested':'No retailer update in this example'}
Policy: ${s.policy==='approved'?'Illustrative reviewed rule DEMO-30-v1':'Conflicting sources; please confirm the applicable window'}
Please check this order and explain eligibility and next steps.`;$('#support-result').innerHTML=`<strong>Details prepared. They stay connected to this visit.</strong><pre>${esc(text)}</pre>`;render();});
$('.dialog-close').addEventListener('click',()=>$('#support-dialog').close());
$('#support-dialog').addEventListener('close',()=>$('#status-content [data-action="support"]')?.focus());
$('#demo-scenario').addEventListener('change',e=>reset(e.target.value));
$('#policy-mode').addEventListener('change',e=>{s.policy=e.target.value;s.alreadyNotified=false;render();});
$('#merchant').addEventListener('change',()=>reset($('#demo-scenario').value));
$('#start-visit').addEventListener('click',()=>{$('#demo-scenario').value='fresh';reset();toast('Demo retailer visit saved. Return here to check the order.');});
$('#reset-demo').addEventListener('click',()=>{$('#demo-scenario').value='fresh';$('#policy-mode').value='conflict';$('#merchant').value='flipkart';reset();toast('Example reset.');});
reset();
